import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  当前世界: z.string().prefault('战姬'),
  原创主角模式: z.string().prefault('取代'),
  user: z.object({
    名字: z.string().prefault(''),
    身份: z.string().prefault('亚尔萨斯伯爵'),
    性别: z.string().prefault('男'),
    当前位置: z.string().prefault('迪南特平原'),
  }),
  关系网: z.record(z.string(), z.object({
    好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    信任度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    关系: z.string().prefault('陌生人'),
  })).prefault({}),
  剧情: z.object({
    当前卷: z.coerce.number().transform(v => _.clamp(v, 1, 18)).prefault(1),
    当前章节: z.string().prefault('迪南特战役'),
    章节内已完成事件: z.string().prefault(''),
    关键事件: z.string().prefault('被艾莲俘虏'),
    模式: z.string().prefault('日常'),
    推进许可: z.boolean().prefault(false),
  }),
});

$(() => {
  registerMvuSchema(Schema);
});

// 根据开场白swipe自动切换战姬/冻涟世界书条目（按名称匹配，导入即用）
var SENKI_NAMES = ['堤格尔维尔穆德·冯伦', '艾蕾欧诺拉·维尔塔利亚', '琉德米拉·露利叶',
  '苏菲亚·欧贝达斯', '亚莉莎德拉·阿尔夏芬', '伊莉莎维塔·法米那',
  '凡伦蒂娜·葛林卡·埃斯堤斯', '奥尔嘉·塔姆', '蒂塔', '莉姆亚莉夏',
  '蕾琪', '罗兰', '战姬 第', 'EJS 战姬章节控制器'];

var REIRIN_NAMES = ['（冻涟）', '冻涟 第', 'EJS 冻涟章节控制器', '拉娜·露利叶', '米莉兹', '琉蒂'];

var SYSTEM_NAMES = ['世界总纲', '叙事规则', '交互范式', '美学纲领', '核查标准', '世界蓝图',
  '生成规则', '世界知识', '叙事指南', '语料库', '场景策略集', 'Step24 回复格式',
  'Initvar', 'Update Rules', 'Variable List', 'Output Format', '主要角色速览', '章节索引'];

let cur = -1, init = false, iv = null;

function isSys(c) {
  for (var i = 0; i < SYSTEM_NAMES.length; i++) {
    if (c === SYSTEM_NAMES[i]) return true;
    if (c.startsWith('[initvar]')) return true;
    if (c.startsWith('[mvu_update]')) return true;
    if (c.startsWith('EJS 战姬 第')) return true;
    if (c.startsWith('EJS 冻涟 第')) return true;
  }
  return false;
}

// 判断条目属于哪个世界（冻涟关键词优先，因为冻涟条目comment中可能同时含战姬人名）
function getEntryWorld(c) {
  for (var i = 0; i < REIRIN_NAMES.length; i++) {
    if (c.indexOf(REIRIN_NAMES[i]) !== -1) return 'reirin';
  }
  for (var i = 0; i < SENKI_NAMES.length; i++) {
    if (c.indexOf(SENKI_NAMES[i]) !== -1) return 'senki';
  }
  return 'system';
}

async function update(swipe) {
  var lb = TavernHelper.getCurrentCharPrimaryLorebook();
  if (!lb || swipe < 0 || swipe > 5) return;
  var reirin = swipe >= 3;
  try {
    var es = await TavernHelper.getLorebookEntries(lb);
    if (!es || !es.length) return;
    var mod = [];
    for (var i = 0; i < es.length; i++) {
      var e = es[i];
      if (isSys(e.comment || '')) continue;
      var world = getEntryWorld(e.comment || '');
      if (world === 'system') continue;
      var shouldEnable = (world === 'reirin' && reirin) || (world === 'senki' && !reirin);
      if (shouldEnable && !e.enabled) {
        mod.push({ uid: Number(e.uid), enabled: true });
      } else if (!shouldEnable && e.enabled) {
        mod.push({ uid: Number(e.uid), enabled: false });
      }
    }
    if (mod.length > 0) {
      await TavernHelper.setLorebookEntries(lb, mod);
      console.log('Swipe ' + swipe + ': updated ' + mod.length + ' entries');
    }
  } catch (err) {}
}

async function getIdx() {
  try {
    var ms = await TavernHelper.getChatMessages(0, { include_swipe: true });
    if (!ms || !ms[0] || !ms[0].swipes) return -1;
    return ms[0].swipe_id || 0;
  } catch (e) { return -1; }
}

async function monitor() {
  try {
    var idx = await getIdx();
    if (cur !== idx && idx >= 0) {
      var old = cur; cur = idx;
      if (init && old >= 0) {
        var w = idx >= 3 ? '冻涟' : '战姬';
        var m = ['原作', '取代', '共存'][idx % 3];
        toastr.info(w + ' - ' + m, '世界切换');
      }
      await update(idx);
    }
  } catch (e) {}
}

function start() {
  if (iv) clearInterval(iv);
  iv = setInterval(monitor, 500);
}

$(function () {
  start();
  if (typeof eventOn === 'function' && typeof tavern_events === 'object' && tavern_events.MESSAGE_SWIPED) {
    eventOn(tavern_events.MESSAGE_SWIPED, async function (mid) {
      if (mid === 0) await monitor();
    });
  }
  setTimeout(async function () { await monitor(); init = true; }, 1500);
});
